"""Configuration models for the Deepgram ASR engines."""

from typing import Optional

from pydantic import ConfigDict, model_validator
from typing_extensions import Literal

from rasa.core.channels.voice_stream.asr.asr_engine import (
    ASRConfigError,
    ASREngineConfig,
)

from .constants import DEEPGRAM_API_V1, DEEPGRAM_API_V2


class DeepgramASRConfigBase(ASREngineConfig):
    """Shared connection settings for Deepgram ASR engines."""

    endpoint: Optional[str] = None

    model_config = ConfigDict(extra="forbid")


class DeepgramASRConfig(DeepgramASRConfigBase):
    """Configuration for Deepgram Nova ASR."""

    version: Literal["v1"] = DEEPGRAM_API_V1
    endpointing: Optional[int] = None
    smart_format: Optional[bool] = None
    utterance_end_ms: Optional[int] = None

    @model_validator(mode="after")
    def _validate_language_map_has_language(self) -> "DeepgramASRConfig":
        """Require each Nova language-map entry to specify a language code."""
        for rasa_lang, entry in (self.language_map or {}).items():
            if not entry.language:
                if entry.model and entry.model.startswith("flux"):
                    raise ASRConfigError(
                        f"Deepgram language_map entry for '{rasa_lang}' uses "
                        f"the Flux model '{entry.model}' with the 'deepgram' "
                        f"ASR, which only supports Nova models. Set the ASR "
                        f"name to 'deepgram_flux' instead."
                    )
                raise ASRConfigError(
                    f"Deepgram language_map entry for '{rasa_lang}' is missing "
                    f"a 'language' value (e.g. 'en'). Deepgram requires an "
                    f"explicit language code for each entry."
                )
        return self


DeepgramV1ASRConfig = DeepgramASRConfig


class DeepgramFluxASRConfig(DeepgramASRConfigBase):
    """Configuration for Deepgram Flux ASR."""

    version: Literal["v2"] = DEEPGRAM_API_V2
    eot_threshold: Optional[float] = None
    eot_timeout_ms: Optional[int] = None
